use std::{any::Any,cell::Cell,hash::{Hash,Hasher},hint::black_box,marker::PhantomData,mem,ops::Deref,ptr::NonNull,rc::{Rc,Weak}};

#[cfg(not(raw))] struct Carrier(Rc<dyn Any>);
#[cfg(raw)] struct Carrier(NonNull<dyn Any>, PhantomData<Rc<dyn Any>>);
impl Carrier {
    #[inline] fn new(x: Rc<dyn Any>) -> Self {
        #[cfg(not(raw))] {Self(x)}
        #[cfg(raw)] {Self(NonNull::new(Rc::into_raw(x).cast_mut()).unwrap(), PhantomData)}
    }
    #[inline] fn pointer(&self) -> *const dyn Any {
        #[cfg(not(raw))] {Rc::as_ptr(&self.0)}
        #[cfg(raw)] {self.0.as_ptr()}
    }
    #[inline] fn weak(&self) -> Weak<dyn Any> {
        #[cfg(not(raw))] {Rc::downgrade(&self.0)}
        #[cfg(raw)] {
            let p=self.0.as_ptr();
            // Add a separate owned reference for the temporary Rc, which drops normally.
            unsafe{ Rc::increment_strong_count(p); Rc::downgrade(&Rc::from_raw(p)) }
        }
    }
}
impl Clone for Carrier {
    #[cfg_attr(shared,inline(never))] #[cfg_attr(not(shared),inline)]
    fn clone(&self)->Self {
        #[cfg(not(raw))] {Self(self.0.clone())}
        #[cfg(raw)] {unsafe{Rc::increment_strong_count(self.0.as_ptr())} Self(self.0,PhantomData)}
    }
}
#[cfg(raw)] impl Drop for Carrier {
    #[cfg_attr(shared,inline(never))] #[cfg_attr(not(shared),inline)]
    fn drop(&mut self){ unsafe{drop(Rc::from_raw(self.0.as_ptr()))} }
}
#[repr(transparent)] struct Handle<T:'static>(Carrier,PhantomData<T>);
impl<T:'static> Handle<T> {
    fn make(x:T)->Self { Self(Carrier::new(Rc::new(x)),PhantomData) }
    fn upcast(self)->Handle<Base> where T:BasePrefix { Handle(self.0, PhantomData) }
    fn is_eq<U:'static>(&self,y:&Handle<U>)->bool {
        #[cfg(identity)] { Rc::ptr_eq(&self.0.0, &y.0.0) }
        #[cfg(not(identity))] { std::ptr::addr_eq(self.0.pointer(),y.0.pointer()) }
    }
    fn weak(&self)->Weak<dyn Any>{self.0.weak()}
}
impl<T:'static> Clone for Handle<T>{#[inline] fn clone(&self)->Self {Handle(self.0.clone(),PhantomData)}}
impl<T:'static> Hash for Handle<T>{#[inline] fn hash<H:Hasher>(&self,s:&mut H){(self.0.pointer().cast::<()>() as usize).hash(s)}}
impl<T:'static> Deref for Handle<T>{type Target=T;#[inline] fn deref(&self)->&T{unsafe{&*self.0.pointer().cast::<T>()}}}
fn upgrade(w:&Weak<dyn Any>)->Option<Handle<Base>> {w.upgrade().map(|x|Handle(Carrier::new(x),PhantomData))}
#[repr(C)] struct Base{value:Cell<u64>,tag:usize}
unsafe trait BasePrefix{} // Each implementing repr(C) object has Base as its first field.
unsafe impl BasePrefix for Base{}
#[repr(C)] struct Plain<const N:usize>{base:Base, extra:[u64;3]}
#[repr(C,align(64))] struct Align<const N:usize>{base:Base, extra:[u64;3]}
unsafe impl<const N:usize> BasePrefix for Plain<N>{}
unsafe impl<const N:usize> BasePrefix for Align<N>{}
fn base(n:usize)->Base{Base{value:Cell::new((n*13+7) as u64),tag:n}}
fn plain<const N:usize>(n:usize)->Handle<Plain<N>> {Handle::make(Plain{base:base(n),extra:[3,5,7]})}
fn align<const N:usize>(n:usize)->Handle<Align<N>> {Handle::make(Align{base:base(n),extra:[3,5,7]})}

