#![allow(dead_code,unused_imports)]
include!("core.rs");
use std::{collections::hash_map::DefaultHasher,panic::{catch_unwind,AssertUnwindSafe}};
fn digest<T:'static>(h:&Handle<T>)->u64 {let mut s=DefaultHasher::new();h.hash(&mut s);s.finish()}
fn qa(){
 assert_eq!(mem::size_of::<Handle<Base>>(),2*mem::size_of::<usize>());assert_eq!(mem::size_of::<Option<Handle<Base>>>(),mem::size_of::<Handle<Base>>());
 let x=align::<1>(7);let addr=x.0.pointer().cast::<()>() as usize;assert_eq!(addr%64,0);
 let w=x.weak();assert_eq!(w.strong_count(),1);let y=x.clone().upcast();assert!(x.is_eq(&y));assert_eq!(digest(&x),digest(&y));
 drop(x);assert_eq!(w.strong_count(),1);assert!(upgrade(&w).unwrap().is_eq(&y));drop(y);assert!(upgrade(&w).is_none());
 struct Watch(Rc<Cell<usize>>);impl Drop for Watch{fn drop(&mut self){self.0.set(self.0.get()+1)}}
 #[repr(C,align(64))] struct P {base:Base,watch:Watch} unsafe impl BasePrefix for P {}
 let count=Rc::new(Cell::new(0));let h=Handle::make(P{base:base(17),watch:Watch(count.clone())}).upcast();let w=h.weak();
 let panic=catch_unwind(AssertUnwindSafe(move||{let _owned=h.clone();let _h=h;std::panic::panic_any(119u32)}));
 assert_eq!(*panic.unwrap_err().downcast::<u32>().unwrap(),119);assert!(upgrade(&w).is_none());assert_eq!(count.get(),1);
}
#[inline(never)] fn run(lane:usize,v:&[Handle<Base>],weak:&[Weak<dyn Any>],iterations:usize)->u64 {
 let mut acc=0u64;let len=v.len();
 macro_rules! bench {($step:expr)=>{for i in 0..iterations {let j=(i.wrapping_mul(40503)>>4)&(len-1);acc=acc.wrapping_add($step(j,i))}}}
 match lane {
  0=>bench!(|j:usize,_|black_box(&v[j]).value.get()),
  1=>bench!(|j:usize,_|{let x=black_box(v[j].clone());x.value.get()}),
  2=>bench!(|j:usize,_|{let x=black_box(upgrade(black_box(&weak[j])).unwrap());x.value.get()}),
  3=>bench!(|j:usize,i:usize|{let t=if i&1==0 {j}else{j.wrapping_add(1)&(len-1)};black_box(&v[j]).is_eq(black_box(&v[t]))as u64}),
  4=>bench!(|j:usize,_|{let w=black_box(v[j].weak());let x=black_box(upgrade(&w).unwrap());x.value.get()}),
  _=>unreachable!()
 };black_box(acc)
}
#[repr(C)]struct Timespec{secs:i64,nanos:i64}
unsafe extern "C"{fn clock_gettime(clock:i32,ts:*mut Timespec)->i32;}
fn clock()->i64{let mut t=Timespec{secs:0,nanos:0};assert_eq!(unsafe{clock_gettime(3,&mut t)},0);t.secs*1_000_000_000+t.nanos}
fn main(){if std::env::args().nth(1).as_deref()==Some("qa"){qa();return}
 let seed:usize=std::env::args().nth(1).unwrap().parse().unwrap();let n=1<<20;
 let v:Vec<_>=(0..512).map(|i|match i%4{0=>plain::<0>(i).upcast(),1=>align::<1>(i).upcast(),2=>plain::<2>(i).upcast(),_=>align::<3>(i).upcast()}).collect();
 let w:Vec<_>=v.iter().map(Handle::weak).collect();
 for k in 0..5 {let lane=(k+seed)%5;let a=clock();let checksum=run(lane,black_box(&v),black_box(&w),n);let dur=clock()-a;println!("{} {} {}",lane,checksum,dur);}
}

